static inline const char *pxWeaponNameAt(uint32_t weaponIdx) {
    if (weaponIdx >= kPxWeaponCount) return "";
    return kPxWeaponNames[weaponIdx];
}

static inline uint32_t pxSkinCountForWeapon(uint32_t weaponIdx) {
    if (weaponIdx >= kPxWeaponCount) return 0;
    uint32_t count = 0;
    for (uint32_t i = 0; i < kPxSkinCount; i++) {
        if (kPxSkinCatalog[i].weaponIndex == weaponIdx) count++;
        else if (count > 0) break; // Catalog is grouped by weapon
    }
    return count;
}

static inline const PxSkinEntry *pxSkinForWeaponAt(uint32_t weaponIdx, uint32_t skinIndexInWeapon) {
    if (weaponIdx >= kPxWeaponCount) return NULL;
    uint32_t seen = 0;
    for (uint32_t i = 0; i < kPxSkinCount; i++) {
        if (kPxSkinCatalog[i].weaponIndex == weaponIdx) {
            if (seen == skinIndexInWeapon) return &kPxSkinCatalog[i];
            seen++;
        } else if (seen > 0) {
            break;
        }
    }
    return NULL;
}

